-- GUS-242 step 1f — the ingredient-category vocabulary
--
-- Generated by scripts/emit_ingredients_1f_sql.py from
-- /tmp/ingredient_categories_1f.json. Do not hand-edit: regenerate.
--
-- 380 FoodOn-derived rows (EFSA FOodex2 groups and
-- classes, each with its FoodOn ID) plus 54 project
-- rows. 434 in total.
--
-- The plan's rule: FoodOn supplies IDENTIFIERS ONLY; the labels and
-- definitions are our own. So the FoodOn-derived rows carry the ID
-- and the parent link, and the project rows keep their own slug,
-- name and description — the dishes reference them by id.
--
-- Idempotent: re-running inserts 0 rows and changes no parent.

\set ON_ERROR_STOP on

-- IDEMPOTENT
--
-- Safe to re-apply: the guard checks that the data is present AND
-- that this migration has not already been applied.
--
-- The "already applied" marker for 0020: every FoodOn-derived row
-- is present AND the parent links are in place.
--
-- The counts are the ones this migration actually produces: 435
-- rows, of which 380 carry a FoodOn ID (the 'vinegar' project row
-- inherits the ID of the FoodOn class it collided with) and 41
-- carry a parent.
SELECT
  EXISTS (SELECT 1 FROM ingredient_categories)
  AND NOT (
    (SELECT count(*) FROM ingredient_categories WHERE foodon_id IS NOT NULL) = 380
    AND
    (SELECT count(*) FROM ingredient_categories WHERE parent_id IS NOT NULL) = 41
  ) AS have_data \gset
\if :have_data
\echo 'GUS-242: the seeded data is present and this migration is not yet applied - running it'

