-- =====================================================================
-- POST-ASSERTIONS
-- =====================================================================

DO $$
DECLARE n int;
BEGIN
  -- Every row is present.
  SELECT count(*) INTO n FROM ingredient_categories;
  IF n < 434 THEN
    RAISE EXCEPTION 'Q1 failed: expected at least 434 ingredient categories, found %', n;
  END IF;

  -- Every FoodOn ID is distinct (the DB enforces this with a
  -- partial unique index, so this can only fail if the index is
  -- missing — which would mean the vocabulary is not protected).
  SELECT count(*) INTO n FROM (
    SELECT foodon_id FROM ingredient_categories
     WHERE foodon_id IS NOT NULL
     GROUP BY foodon_id HAVING count(*) > 1) z;
  IF n <> 0 THEN
    RAISE EXCEPTION 'Q2 failed: % FoodOn IDs are used more than once', n;
  END IF;

  -- The hierarchy must be acyclic.
  --
  -- The walk starts at each row and steps to its parent. A cycle
  -- exists when the walk comes back to a node it has already
  -- visited AT A LATER LEVEL than the start — `lvl > 1` is what
  -- distinguishes 'arrived back at the start' from 'the first
  -- step'. Without it the query reports every row as a cycle;
  -- with it, a real cycle is reported exactly once per member.
  WITH RECURSIVE walk AS (
    SELECT id AS start, id AS node, 1 AS lvl FROM ingredient_categories
     WHERE parent_id IS NOT NULL
    UNION ALL
    SELECT w.start, p.parent_id, w.lvl + 1
      FROM walk w
      JOIN ingredient_categories p ON p.id = w.node
     WHERE p.parent_id IS NOT NULL
  )
  SELECT count(*) INTO n FROM (
    SELECT DISTINCT start FROM walk WHERE lvl > 1 AND node = start
  ) z;
  IF n <> 0 THEN
    RAISE EXCEPTION 'Q3 failed: the ingredient hierarchy has % cycles', n;
  END IF;

  -- Every parent_id must point at a real row.
  SELECT count(*) INTO n FROM ingredient_categories c
   WHERE c.parent_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM ingredient_categories p WHERE p.id = c.parent_id);
  IF n <> 0 THEN
    RAISE EXCEPTION 'Q4 failed: % rows have a dangling parent', n;
  END IF;

  -- The 55 pre-existing categories must still be present, with their
  -- original slugs. A dish must never lose an ingredient.
  SELECT count(*) INTO n FROM ingredient_categories
   WHERE slug IN (
     'allium', 'aromatic-base', 'beef', 'beverage', 'bread', 'broth', 'cheese', 'chicken',
     'chili', 'citrus', 'coconut', 'dairy', 'dough', 'egg', 'fat', 'fermented',
     'fish', 'fruit', 'fumigation', 'game', 'grain', 'herb', 'leafy-green', 'legume',
     'liquid', 'meat', 'noodle', 'nut', 'octopus', 'offal', 'oil', 'paste',
     'pickle', 'pork', 'poultry', 'produce', 'red-meat', 'rice', 'root-vegetable', 'salt',
     'sauce', 'savoury', 'seafood', 'seed', 'shellfish', 'shrimp', 'spice', 'stock',
     'sugar', 'sweet', 'sweetener', 'vegetable', 'white-meat', 'wrapper'
   );
  IF n <> 54 THEN
    RAISE EXCEPTION 'Q5 failed: expected all 54 existing categories, found %', n;
  END IF;

  -- The dishes' ingredient links must be intact.
  SELECT count(*) INTO n FROM dish_dish_ingredient_categories;
  IF n = 0 THEN
    RAISE EXCEPTION 'Q6 failed: no dish ingredient links remain';
  END IF;
  RAISE NOTICE 'ingredient categories: % rows, % with a FoodOn ID',
    (SELECT count(*) FROM ingredient_categories),
    (SELECT count(*) FROM ingredient_categories WHERE foodon_id IS NOT NULL);
END $$;

COMMIT;

\else
\echo 'GUS-242: the seeded data is NOT present, or this migration is already applied - skipping it'
\endif
